/* ============================================================
   DATA-CASOS.JS — Declinaciones de las palabras del léxico AZBUKA
   ------------------------------------------------------------
   Total: 3229 palabras (todas las entradas de data-lexicon.js con
   categoría sustantivo, adjetivo, pronombre, determinante o numeral).
   Generado el 23/09/2026. Ordenado por ID.
   Actualizado el 24/09/2026: лист y ко́рпус separados en dos entradas
   (CMR-05469, CMR-05470); plurales de дя́дя, се́ктор y ноль unificados
   con el léxico.

   QUÉ HAY ACÁ Y QUÉ NO
   Este archivo guarda SOLO las formas declinadas. Todo lo demás
   (traducción, categoría, género, animacidad, número, transliteración,
   IPA) se lee de data-lexicon.js por el mismo ID. Las explicaciones de
   los casos y de los campos extra viven en data-gramatica.js
   (GRAMATICA_CASOS y GRAMATICA_FORMAS). Nunca duplicar acá datos que ya
   estén en el léxico central.

   Cargar DESPUÉS de data-lexicon.js:
     <script src="data-lexicon.js"></script>
     <script src="data-gramatica.js"></script>
     <script src="data-casos.js"></script>

   ORDEN FIJO DE LOS CASOS en todas las listas de 6 formas:
     nominativo · genitivo · dativo · acusativo · instrumental · preposicional

   FORMATO DE CADA PALABRA (clave = ID del léxico, "CMR-xxxxx")
     ru     palabra con acento. Ancla de control: sin el acento tiene
            que ser idéntica a LEXICON_COMER[id].ru.
     tipo   cómo se arma la tabla:

     "sustantivo"   sg y pl: 6 formas cada uno. null = ese número no
                    existe (singularia / pluralia tantum).
                    adjetival:true  → sustantivo que se declina como
                                      adjetivo (учёный, столо́вая).
                    loc2  (opcional) locativo, SIEMPRE con su
                          preposición: "в лесу́", "на полу́".
                    partitivo (opcional) genitivo partitivo coloquial
                          (ча́ю, са́хару). Va aparte de la tabla; la página
                          lo muestra junto al genitivo.
     "adjetivo"     adjetivos, determinantes, ordinales y los numerales
                    con género (оди́н, два, о́ба, полтора́).
                    m · f · n · pl: 6 formas cada uno (24 en total).
                    El acusativo del masculino y del plural es un par
                    [inanimado, animado]: ["но́вый","но́вого"].
                    null en un género = no existe (два no tiene plural).
                    corta (opcional) forma corta { m, f, n, pl }; null
                          en una posición = no se usa. Solo en adjetivos
                          calificativos, no en los de relación
                          (госуда́рственный, вое́нный…).
     "personal"     pronombres personales y себя́. formas: 6 formas.
                    n  → las mismas formas con н- que se usan después
                         de preposición (у него́, с ни́ми, о нём).
                    alt / altN → variante literaria de una forma
                         (мно́ю, е́ю, не́ю), por nombre de caso.
     "serie"        pronombres y numerales sin género: una sola lista de
                    6 formas en "formas" (кто, что, три, пять, сто…).
                    numero:"pl" → la palabra es plural (все, мно́гие).
                    El acusativo puede ser un par [inanimado, animado]
                    (три / трёх).
     "indeclinable" no cambia (кафе́, метро́, его́ como posesivo).
     nota   (opcional) aclaración de uso en español rioplatense.

   null en una posición = esa forma no existe o no se usa. La página la
   muestra como "—".

   ACENTO: marcado con U+0301 (acento agudo combinable) sobre la vocal
   tónica. No se marca en palabras de una sola vocal ni cuando la
   palabra lleva ё (ё siempre es tónica). Las formas declinadas llevan
   ё siempre que corresponde (всё, её, лёгкий, учёного).

   FUENTES Y LICENCIA
   Formas tomadas de los datos de OpenRussian.org (Badestrand/
   russian-dictionary, CC BY-SA 4.0), contrastadas con el analizador
   morfológico pymorphy3 (diccionario OpenCorpora, CC BY-SA) y con los
   índices de acentuación del Diccionario gramatical de Zalizniak.
   Los adjetivos regulares se generaron por regla y se contrastaron con
   las dos primeras fuentes. Los casos dudosos se revisaron y
   corrigieron a mano (ver INFORME_DATA_CASOS.md). Por derivar de datos
   CC BY-SA, las tablas de este archivo se distribuyen bajo CC BY-SA 4.0
   (ver LICENSE-CONTENT). Las notas son redacción propia de AZBUKA.
   ============================================================ */


